text:
{
  "components": [
    {
      "type": "claim",
      "quote": "En vertu de la loi sur la transparence (Ltrans), vous pouvez demander à consulter les documents officiels de l’Office fédéral de l’énergie (OFEN).",
      "gist": "Under the Transparency Act (Ltrans), you can request to consult official documents of the Federal Office of Energy (OFEN)."
    },
    {
      "type": "condition",
      "quote": "Ce droit d’accès s’applique aux documents finalisés après le 1er juillet 2006.",
      "gist": "This access right applies to documents finalized after July 1, 2006."
    },
    {
      "type": "obligation",
      "quote": "Elle doit contenir suffisamment d’informations pour que l’OFEN puisse identifier les documents que vous souhaitez consulter.",
      "gist": "The request must contain enough information for OFEN to identify the documents you wish to consult."
    },
    {
      "type": "other",
      "quote": "Veuillez donc lui transmettre le plus de détails possibles concernant ces documents.",
      "gist": "Please therefore provide as many details as possible about these documents."
    },
    {
      "type": "other",
      "quote": "Il peut être utile d’indiquer la date d’établissement, le titre, les références, le domaine précis ou la période concernée.",
      "gist": "It may be useful to indicate the date of creation, title, references, specific field, or relevant period."
    }
  ]
}
